/* =====================================================================
   8) THEORY OF CHANGE WORKSHEET
   ===================================================================== */
const TOC_SRC = [['https://www.thinknpc.org/publications/inspiring-impact-2/', 'NPC: Inspiring Impact'], ['https://www.ncvo.org.uk/help-and-guidance/strategy-and-impact/impact-evaluation/', 'NCVO: impact and evaluation']];
const TOC_Q = [['prob', 'What’s the problem?', 'e.g. Older people in Lewsey are lonely and don’t know where to get help'], ['who', 'Who are the people you work with?', 'e.g. People over 70 living alone in LU4'], ['acts', 'What will you do? (activities)', 'e.g. Weekly lunch club, phone befriending, help with forms'], ['outp', 'What will you deliver? (outputs: things you can count)', 'e.g. 48 lunches, 300 calls, 60 people helped with forms'], ['out1', 'What changes soon after? (short-term outcomes)', 'e.g. People make new friends and know who to call'], ['out2', 'What changes later? (longer-term outcomes)', 'e.g. People feel less lonely and stay independent at home'], ['imp', 'What’s the big change you’re working towards? (impact)', 'e.g. No older person in Lewsey feels alone'], ['ass', 'What has to be true for this to work? (assumptions)', 'e.g. People can get to the venue; volunteers stay with us'], ['meas', 'How will you know? (measures)', 'e.g. Attendance, a short loneliness question at the start and after 6 months, quotes']];
const tocRes = a => { const box = (c, t, v) => `<div class="${c}"><b>${t}</b>${esc(v || '…')}</div>`;
  const txt = TOC_Q.map(([k, q]) => `${q.replace(/\?.*$/, '?')}\n${a[k] || '…'}`).join('\n\n');
  return { h: 'Theory of change', print: true,
    html: `<div class="t3toc">${box('c1', 'Problem', a.prob)}${box('c2', 'People', a.who)}${box('c3', 'Activities', a.acts)}${box('c4', 'Outputs', a.outp)}${box('c5', 'Outcomes', [a.out1, a.out2].filter(Boolean).join(' → '))}${box('c6', 'Impact', a.imp)}</div>
    <div class="t3as"><b>Assumptions:</b> ${esc(a.ass || '…')}</div><div class="t3as" style="border-color:#16865F"><b>Measures:</b> ${esc(a.meas || '…')}</div>
    <div class="t3card"><h4>Check it reads well</h4><p class="note">Read it from left to right with “so that” between each box: <i>we work with ${esc(a.who || '[people]')} and run ${esc(a.acts || '[activities]')}, so that ${esc(a.out1 || '[short-term change]')}, so that ${esc(a.out2 || '[longer-term change]')}</i>. If a step doesn’t follow, there’s a gap to fill.</p><ul class="trl"><li>Outcomes are changes for people, not things you do.</li><li>Pick 3 to 5 measures you can really collect. Before-and-after questions show change better than satisfaction scores.</li><li>Pair every number with a real story (with consent).</li></ul></div>
    <div class="row noprint"><a class="btn p sm" href="#bidcheck">Use it in a funding bid</a><a class="btn s sm" href="#impact">Impact report</a></div>${src(TOC_SRC)}`,
    copy: 'THEORY OF CHANGE\n\n' + txt, share: 'Our theory of change, made with the Luton Community Hub worksheet:' }; };
regTool('toc_ws', { route: 'toc', t: 'Theory of change worksheet', d: 'Nine guided steps, from the problem to the measures. You’ll get a one-page diagram with the text, ready to print and use in bids and impact reports.', icon: 'spark', done: 'Your theory of change is ready', btn: 'Make my diagram',
  qs: TOC_Q.map(([k, q, ph]) => q1(k, q, null, { text: 1, long: 1, req: ['prob', 'acts', 'out1'].includes(k) ? 1 : 0, ph })), res: tocRes });
V.toc = () => page('toc', 'Theory of change worksheet', 'Show how what you do leads to the change you want: problem, people, activities, outputs, outcomes, impact, the assumptions behind it and how you’ll measure it, on one page.', tCard('toc_ws'), 'fundsup', 'Funding');

