/* =====================================================================
   10) DATA PROTECTION CHECK
   ===================================================================== */
const DP_SRC = [['https://ico.org.uk/for-organisations/advice-for-small-organisations/', 'ICO: advice for small organisations'], ['https://ico.org.uk/for-organisations/data-protection-fee/', 'ICO: data protection fee'], ['https://ico.org.uk/fee-guide', 'ICO: fee guide'], ['https://ico.org.uk/for-the-public/schools/photos/', 'ICO: photos'], ['https://learning.nspcc.org.uk/safeguarding-child-protection/photography-and-sharing-images', 'NSPCC Learning: photography and sharing images']];
const YN = [['y', 'Yes'], ['n', 'No']];
const DP_Q = [q1('forms', 'Do you collect people’s details on forms (paper or online)?', YN), q1('photos', 'Do you take photos or videos of people?', YN), q1('wa', 'Do you run WhatsApp groups with members, parents or volunteers?', YN), q1('store', 'Where do you keep people’s details?', [['paper', 'Paper files or sign-in sheets'], ['phones', 'Volunteers’ own phones'], ['cloud', 'A shared drive or cloud folder'], ['email', 'In email'], ['sheet', 'Spreadsheets'], ['system', 'A booking or membership system']], { multi: true }), q1('cctv', 'Do you use CCTV?', YN), q1('kids', 'Do you hold children’s details?', YN), q1('sens', 'Do you hold sensitive details?', [['health', 'Health or disability'], ['faith', 'Religion (e.g. a membership list for a place of worship)'], ['eth', 'Ethnicity'], ['money', 'Benefits or money problems'], ['none', 'None of these']], { multi: true }), q1('mail', 'Do you send emails or texts about news, events or appeals?', YN), q1('share', 'Do you share people’s details with other organisations?', YN), q1('notice', 'Do you have a privacy notice?', [['y', 'Yes'], ['n', 'No'], ['u', 'Not sure']]), q1('breach', 'Do you know what to do if data is lost or sent to the wrong person?', [['y', 'Yes'], ['n', 'No']]), q1('fee', 'Have you checked whether you need to pay the ICO fee?', [['y', 'Yes'], ['n', 'No']])];
const dpRes = a => { const s = a.store || [], sens = (a.sens || []).filter(x => x !== 'none'), todo = [];
  const add = (p, t, d, links = []) => todo.push({ p, t, d, links });
  if (a.notice !== 'y') add(1, 'Write a privacy notice', 'Say what you collect, why, your lawful basis, who you share it with, how long you keep it and how people can see or delete their data. Share it wherever you collect details.', [['#policies-dataprotection', 'Privacy notice template']]);
  add(a.notice === 'y' ? 3 : 1, 'Pick a lawful basis for each use', 'For most groups it’s consent, contract (e.g. a membership), legitimate interests, or legal obligation. Write down which one you rely on for each thing you do with people’s data.', [['https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/lawful-basis/', 'ICO: lawful basis']]);
  if (a.fee !== 'y') add(1, 'Check the ICO data protection fee', 'Most organisations that handle personal data must pay a yearly fee unless they’re exempt. Some not-for-profits are exempt: the ICO’s short self-assessment tells you. Charities that aren’t exempt pay the Tier 1 fee, £52 a year (£5 less by direct debit).', [['https://ico.org.uk/for-organisations/data-protection-fee/', 'ICO fee self-assessment'], ['#policies-icofee', 'ICO fee checklist']]);
  if (sens.length) add(1, 'Extra care with sensitive details', `You hold ${sens.map(k => lab([['health', 'health'], ['faith', 'religion'], ['eth', 'ethnicity'], ['money', 'financial hardship']], k)).join(', ')} details. Health, religion and ethnicity are “special category” data under UK GDPR, so you need a lawful basis and an extra condition, usually explicit consent or, for religious organisations, the not-for-profit condition for members. ${sens.includes('faith') ? 'A membership or donor list for a place of worship counts, because it shows people’s religion. ' : ''}Limit who can see it.`, [['https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/lawful-basis/special-category-data/', 'ICO: special category data']]);
  if (a.kids === 'y') add(1, 'Protect children’s details', 'Collect only what you need, get parents’ consent where you rely on consent for under-13s online, and lock children’s records away with limited access. Never put children’s names next to their photos online.', [['#policies-safeguarding', 'Safeguarding template']]);
  if (a.photos === 'y') add(a.kids === 'y' ? 1 : 2, 'Get photo consent', 'Ask in writing what photos are for (website, social media, print), how long you’ll keep them and how to withdraw. For under-16s ask a parent and the child too. Mark people who haven’t agreed so photographers can avoid them, and stop using a photo if consent is withdrawn.', [['#policies-photo', 'Photo consent form']]);
  if (a.mail === 'y') add(1, 'Only email or text people who agreed', 'Marketing emails and texts, including fundraising and event news, need people’s consent (or a soft opt-in in limited cases). Include an easy way to unsubscribe every time, and use BCC or a mailing tool so you never show everyone’s address.', [['https://ico.org.uk/for-organisations/direct-marketing-and-privacy-and-electronic-communications/', 'ICO: direct marketing']]);
  if (a.wa === 'y') add(2, 'Set up WhatsApp groups safely', 'In an ordinary group everyone can see each other’s phone numbers. Tell people that before adding them, add only people who agreed, use announcement-only groups for news, remove people who leave, and never share children’s photos or private details in groups.', []);
  if (s.includes('phones')) add(1, 'Get details off personal phones', 'Keep people’s details on organisation accounts, not volunteers’ own phones. If phones must be used, set a passcode and delete details when the volunteer leaves or the activity ends.', []);
  if (s.includes('paper')) add(2, 'Lock away paper records', 'Keep sign-in sheets and forms in a locked cabinet, and shred them when you no longer need them.', []);
  if (s.some(k => ['cloud', 'email', 'sheet', 'system'].includes(k))) add(2, 'Secure your accounts', 'Strong passwords and 2-step login on every account, access only for people who need it, and remove access the day someone leaves.', [['https://www.ncsc.gov.uk/collection/small-charity-guide', 'NCSC: small charity guide']]);
  if (a.cctv === 'y') add(2, 'Put up CCTV signs and set rules', 'Signs saying CCTV is in use and who to contact, a reason for each camera, footage kept only as long as needed and a named person who can view it.', [['https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/cctv-and-video-surveillance/', 'ICO: CCTV']]);
  if (a.share === 'y') add(2, 'Check you’re allowed to share', 'Only share details with other organisations when you have a lawful basis and people know it may happen (it should be in your privacy notice). Safeguarding concerns are different: share them with the right agency.', []);
  add(2, 'Set how long you keep things', 'Decide how long you keep each kind of record, then delete or shred on a regular date each year. Gift Aid records have their own rules.', [['#policies-dataprotection', 'Data protection policy']]);
  if (a.breach !== 'y') add(1, 'Have a breach plan', 'If data is lost, stolen or sent to the wrong person: contain it, write it down, decide the risk to people, and report it to the ICO within 72 hours if there’s a risk to people. Tell the people affected if the risk is high.', [['https://ico.org.uk/for-organisations/report-a-breach/', 'ICO: report a breach'], ['#policies-dataprotection', 'Breach log template']]);
  add(3, 'Answer requests for people’s own data', 'Anyone can ask for a copy of the data you hold about them. You have one month to reply, and it’s usually free.', []);
  todo.sort((x, y) => x.p - y.p);
  const P = { 1: ['hi', 'Do first'], 2: ['md', 'Do soon'], 3: ['lo', 'Keep in mind'] }, tk = store.get('dpticks', {}) || {};
  return { h: `Your data protection to-do list: ${todo.filter(t => t.p === 1).length} to do first`, print: true,
    html: `<ul class="lglist">${todo.map((t, i) => `<li class="lgi${tk[t.t] ? ' done' : ''}"><label class="lgck"><input type="checkbox" data-dptick="${esc(t.t)}" ${tk[t.t] ? 'checked' : ''}><span class="box" aria-hidden="true">${si('check')}</span><span><b>${esc(t.t)}</b></span></label><span class="t3rate ${P[t.p][0]}">${P[t.p][1]}</span><p>${esc(t.d)}</p>${t.links.length ? `<div class="row">${t.links.map(([u, n]) => /^https?:/.test(u) ? lnk(u, n) : `<a class="btn s sm" href="${u}">${esc(n)}</a>`).join('')}</div>` : ''}</li>`).join('')}</ul>
    <div class="t3card"><h4>Want a fuller check?</h4><p class="note">The ICO has a free self-assessment for small organisations, and free advice by phone and live chat.</p><div class="row">${ext('https://ico.org.uk/for-organisations/advice-for-small-organisations/', 'ICO help for small organisations')}<a class="btn s sm" href="#policies">Policy library</a></div></div>
    <p class="note">Guidance, not legal advice. The ICO is the UK’s data protection regulator and its guidance has the final word.</p>${src(DP_SRC)}`,
    copy: 'Data protection to-do list\n\n' + todo.map(t => `[${P[t.p][1]}] ${t.t}\n${t.d}`).join('\n\n') + srcTxt(DP_SRC.slice(0, 2)),
    share: 'Our data protection to-do list from the Luton Community Hub. Worth doing for your group too:' }; };
regTool('dp_chk', { route: 'dpcheck', t: 'Data protection check', d: 'Twelve quick questions about the details you hold. You’ll get a plain to-do list in order of priority, with templates and the ICO links you need.', icon: 'shield', done: 'Here’s your to-do list', qs: DP_Q, res: dpRes });
document.addEventListener('change', e => { const c = e.target.closest('[data-dptick]'); if (!c) return; const tk = store.get('dpticks', {}) || {}; c.checked ? tk[c.dataset.dptick] = Date.now() : delete tk[c.dataset.dptick]; store.set('dpticks', tk); c.closest('.lgi')?.classList.toggle('done', c.checked); });
